\label{assum}
\begin{enumerate}
\item the \textsc{brw}\xspace is critical: $\E[\chi(\R)] = M(\R) = 1$,
\item the \textsc{brw}\xspace is centered: $\E\left[ \int x \d\chi(x)\right] = \int x \d M(x) = 0$,
\item $\E[\chi(\R)^2] = \sigma^2 + 1 \in (1, \infty)$, 
\item $\E\left[\int x^2 \d\chi(x)\right] = \int x^2 \d M(x) = \eta^2 \in (0, \infty)$,
\item $\P(\Lambda>r) = o(r^{-4})$ as $r\to\infty$, 
\item $\E[D] = 1$. 
\end{enumerate}

\label{th:main-tail}
Under Assumptions \ref{assum}, asymptotically as $r\to\infty$, 
\[ \P\left(\sup_{v\in T} \Lambda_v > r\right) \sim \frac{6\eta^2}{\sigma^2 r^2} . \]

\label{cor:main-tail}
Under Assumptions \ref{assum}, asymptotically as $r\to\infty$, 
\[ \P\left(\sup_{v\in T} X_v > r\right) \sim \frac{6\eta^2}{\sigma^2 r^2} . \]

\label{th:main-condition}
Under Assumptions \ref{assum}, if $M$ is supported on $\Z$ and has maximal span $1$ and if $\Lambda$ is $\N$-valued, then asymptotically as $r\to\infty$ with $r\in \N$,  
\[ \P\left(\sup_{v\in T} \Lambda_v = r\right) \sim \frac{12 \eta^2}{\sigma^2 r^3} . \]

Define for every $x,y\in\kX$
\begin{equation}\label{eq:def-M}
M_{x,y} = \E\left[\chi^{(x)}(\R \times \{y\}) \right]
\end{equation}
the average number of type $y$ offspring of a type $x$ vertex, and assume that $M_{x,y} < \infty$ for every $x,y$.

\label{lem:simpler-assum}
\begin{enumerate}
\item Assumption \ref{assum-multitype}.2 holds if $N_{y,z} = 0$ for every $y,z\in\kX$.

\item The condition $\eta^2>0$ in assumption \ref{assum-multitype}.4 holds if for at least one pair $(y,z)\in\kX^2$ the mean measure $A \mapsto \E[\chi^{(y)}(A\times\{z\})]$ is non-zero and not supported on a single point.  
\end{enumerate}

\label{cor:maps}
Let $\bm$ be a positive pointed and rooted planar map distributed under the probability distribution $Z_\bq^{-1} w_\bq(\cdot)$ (this is the Boltzmann distribution), and let $\bd$ be the distance between its root vertex and its pointed vertex and $N_V$, resp. $N_F$ and $N_E$ its number of vertices, resp. faces or edges. Then letting $\sigma^2 = Z_\bq^2 f_\bq''(Z_q)$ and $c_V = 1$, $c_E=Z_\bq$ and $c_F = Z_\bq-1$, 
as $r\to\infty$, 
\begin{align}
	\P(\bd > r) &\sim 2 r^{-2} , \\
	\P(\bd = r) &\sim 4 r^{-3} ,
\end{align}
and under $\P(\, \cdot \, | \bd = r)$, resp. under $\P(\, \cdot \, | \bd>r)$, we have the convergence in distribution
\[ \frac{1}{\sigma^2 r^4} \left(\frac{N_V}{c_V} , \frac{N_F}{c_F}, \frac{N_E}{c_E}\right) \ulimd r \infty (\bn, \bn, \bn) \]
where recalling $\psi$ from Theorem \ref{th:main-volume-smaller}
\[ \E\left[ \e^{-2\alpha^2 \bn} \right] = \frac{2\alpha}{\sigma^2} \psi\left(\sqrt{\frac{12\alpha}{\sigma^2}}\right) . \]

\label{prop:convolution-equation}
With the convention that $\ln 0 = -\infty$, for every $r\geq 0$
\begin{equation}
h(r) = \E\left[ \ind{\Lambda\leq r} \exp\left( \int \ln h(r-x) \d \chi(x) \right) \right] .
\end{equation}

This is a simple application of the Markov property. Let $(\chi, \Lambda, (X_i)_{1\leq i \leq \chi(\R)}) \sim \BB$ be independent of $(T, (X_v)_{v\in T}, (\Lambda_v)_{v\in T})$, then
\begin{align*}
h(r) &= \E\left[ \ind{\Lambda\leq r} \prod_{i=1}^{\chi(\R)} \P\left( \sup_{v\in T} \Lambda_v \leq r-X_i \right) \right] = \E\left[ \ind{\Lambda\leq r} \prod_{i=1}^{\chi(\R)} h(r-X_i) \right]
\end{align*}
from which we recognize the expression of the Proposition.

\begin{align*}
h(r) &= \E\left[ \ind{\Lambda\leq r} \prod_{i=1}^{\chi(\R)} \P\left( \sup_{v\in T} \Lambda_v \leq r-X_i \right) \right] = \E\left[ \ind{\Lambda\leq r} \prod_{i=1}^{\chi(\R)} h(r-X_i) \right]
\end{align*}

\label{lem:continuity-w-broad}
