&\leq \limsup_{r\to\infty} \frac{w\left( r + \frac{y}{\sqrt{w(r)}}\right)}{w(r)} \leq F_+\left( \frac{\sigma}{\eta} y \right) . \label{eq:continuity-ratio-left}
\end{align}
