For every $0\leq R \leq r$ and every $\delta>0$, define 
\begin{equation}\label{eq:event-E-rRd}
E(r,R,\delta) := \left\{\chi(\R)\leq \frac{\delta}{w(r-R)} \right\} \cap \{ \Lambda \leq R \} .
\end{equation}

Let $(Z, I^{(r,R,\delta)})$ be the couple of random variables with values in $\R\times \{0,1\}$ such that for every positive and measurable $f$, 
\begin{equation}\label{eq:def-ZI}
\E\left[ f(Z, I^{(r,R,\delta)}) \right] = \E\left[ \int f(x,\ind{E(r,R,\delta)}) \d\chi(x) \right] .
\end{equation}

We also define the Markov kernel $((z,i), \Gamma) \mapsto P^{(r,R,\delta)}_{z,i}(\Gamma)$, where $\Gamma$ is a measurable subset of the set of point measures, $i\in\{0,1\}$ and $z\in\R$, such that for every positive and measurable $g$, if $(X_i)_{1\leq i \leq \chi(\R)}$ is a measurable numbering of the atoms of $\chi$, 
\begin{equation}\label{eq:def-Palm}
\E\left[ \sum_{i=1}^{\chi(\R)} g\left(X_i , \ind{E(r,R,\delta)}, \chi - \delta_{X_i} \right) \right] = \E\left[ \int g\left(Z, I^{(r,R,\delta)}, \phi \right) \d P^{(r,R,\delta)}_{Z, I^{(r,R,\delta)}}(\phi) \right] .
\end{equation}

\label{prop:convolution-w}
Under Assumptions \ref{assum} 1. to 4., there exists $\delta^0>0$ and $r_0>0$ such that for every $\delta \in (0,\delta^0)$, $r_\bullet \geq r_0$, $r\geq 2r_\bullet$ and for every $r_\bullet \leq R \leq  r-r_\bullet$, 
\begin{multline}\label{eq:convolution-w}
w(r) = \E\Bigg[ I^{(r,R,\delta)} w(r-Z) \exp\Big( - w(r-Z) - \frac{1}{2} \int w(r-y) \d M^{(r,R,\delta)}_{Z} (y) \\
+ \E\left[ I^{(r,R,\delta)} w(r-Z) \right] \Big) \Bigg] + \mathrm{Remainder}(r,R,\delta) ,
\end{multline}
where
\begin{equation*} 
\frac{1}{90}|\mathrm{Remainder}(r,R,\delta)| \leq \P(\Lambda>R) + \P\left(\chi(\R)>\frac{\delta}{w(r-R)}\right) + (\sigma^2 + 1) w(r-R)^2 \left( w(r-R) + \delta \right) .
\end{equation*}

\begin{multline}\label{eq:convolution-w}
w(r) = \E\Bigg[ I^{(r,R,\delta)} w(r-Z) \exp\Big( - w(r-Z) - \frac{1}{2} \int w(r-y) \d M^{(r,R,\delta)}_{Z} (y) \\
+ \E\left[ I^{(r,R,\delta)} w(r-Z) \right] \Big) \Bigg] + \mathrm{Remainder}(r,R,\delta) ,
\end{multline}

\begin{multline*}
\left| \E\left[ I^{(r,R,\delta)} w(r-Z) (1 + \xi) \right] - \E\left[ I^{(r,R,\delta)} w(r-Z) \e^\xi \right] \right| \leq \E\left[ I^{(r,R,\delta)} w(r-Z) \xi^2 \right] \\
\leq \left( w(r-R) + \frac\delta 2\right) \E\Bigg[ I^{(r,R,\delta)} w(r-Z) \left\{ w(r-Z) + \frac{1}{2} \int w(r-y) \d M^{(r,R,\delta)}_{Z} (y) + \E\left[ I^{(r,R,\delta)} w(r-Z) \right] \right\} \Bigg] \\
\leq \left( w(r-R) + \frac\delta 2\right) \left( \frac{\sigma^2}{2} + 2\right) w(r-R)^2 ,
\end{multline*}

\label{prop:almost-martingale}
For every $n\geq 0$, define the ``discount process'' 
\begin{multline}\label{eq:def-Z}
\kW^{(r)}_n := \left(\prod_{k=0}^{n-1} I_{k+1}\right) \exp\Bigg(- \sum_{k=0}^{n-1} \left( w(S_{k+1}) - \E\left[ I_{k+1} w(S_{k+1}) \, | \, \FF_k \right] \right) \\
- \frac 12 \sum_{k=0}^{n-1} \int w(S_k-y) \d M^{(S_k,R_k,\delta_k)}_{S_k-S_{k+1}}(y) \Bigg) . 
\end{multline}
Define the stopping time 
\[ T = \inf\{n\geq 0 : S_n < 2r_\bullet \text{ or } R_n \notin [r_\bullet, S_n - r_\bullet] \text{ or } \delta_n \notin (0,\delta^0) \} . \]
Define the processes 
\begin{equation}
W^{(r)}_n = \kW^{(r)}_n w(S_n) \quad , \quad Y_n := W^{(r)}_n - \sum_{k=0}^{n-1} \kW^{(r)}_k  \mathrm{Remainder}(S_k, R_k, \delta_k) .
\end{equation}
Then $(Y_{n\wedge T})_{n\geq 0}$ is a martingale, i.e. on the event $\{T > n\}$, 
\begin{equation}\label{eq:almost-mg-ppty}
\E\left[ W^{(r)}_{n+1} | \FF_n\right]  -  W^{(r)}_n = \kW^{(r)}_n \mathrm{Remainder}(S_n, R_n, \delta_n) ,
\end{equation}
where the remainder is given by Proposition \ref{prop:convolution-w}.

\begin{multline}\label{eq:def-Z}
\kW^{(r)}_n := \left(\prod_{k=0}^{n-1} I_{k+1}\right) \exp\Bigg(- \sum_{k=0}^{n-1} \left( w(S_{k+1}) - \E\left[ I_{k+1} w(S_{k+1}) \, | \, \FF_k \right] \right) \\
- \frac 12 \sum_{k=0}^{n-1} \int w(S_k-y) \d M^{(S_k,R_k,\delta_k)}_{S_k-S_{k+1}}(y) \Bigg) . 
\end{multline}

\begin{multline*}
\kW^{(r)}_n = \left(\prod_{k=0}^{n-1} I_{k+1}\right) \exp\Bigg(- \sum_{k=0}^{n-1} \left( I_{k+1} w(S_{k+1}) - \E\left[ I_{k+1} w(S_{k+1}) \, | \, \FF_k \right] \right) \\
- \frac 12 \sum_{k=0}^{n-1} I_{k+1} \int w(S_k-y) \d M^{(S_k,R_k,\delta_k)}_{S_k-S_{k+1}}(y) \Bigg) . 
\end{multline*}

\label{cor:Feynman-Kac}
There exists a function $\underline{\delta} : [0,\infty) \to (0,\delta^0)$ decreasing with $\underline{\delta}(y) \to 0$ as $y\to\infty$ and a function $g:(0,1] \to [0,\infty)$ increasing with $g(x)\to 0$ as $x\to 0$ such that the following holds. 

For every $a\in (0,a_0)$, $A>0$, $y>0$, $\RR>0$, and $r \geq x \geq r_0$ where $a_0, r_0$ is given by Lemma \ref{lem:discount-UI}, setting $\delta_n = \underline{\delta}(y)$ for every $n$ and writing 
\begin{equation*}
\begin{cases}
\tau_x = \inf\{ n\geq 0 : S_n \leq x \} \\
\rho = \inf\{n\geq 0 : S_n-R_n < y \text{ or } R_n < \RR\} \\
T' = \inf(\tau_x, T_a, \rho, A/w(x) \}
\end{cases}
\end{equation*}
then 
\begin{equation}\label{eq:FK}
\left| w(r) - \E\left[ W^{(r)}_{T'}\right] \right| \leq  \frac{100 A}{w(x)} \left( \P(\Lambda > \RR) + w(y)^2 g(w(y))\right) .
\end{equation}

\begin{equation*}
\begin{cases}
\tau_x = \inf\{ n\geq 0 : S_n \leq x \} \\
\rho = \inf\{n\geq 0 : S_n-R_n < y \text{ or } R_n < \RR\} \\
T' = \inf(\tau_x, T_a, \rho, A/w(x) \}
\end{cases}
\end{equation*}

By Proposition \ref{prop:almost-martingale} the process
\[ Y_n := W_n^{(r)} - \sum_{k=0}^{n-1} \kW^{(r)}_k \mathrm{Remainder}(S_k, R_k, \delta_k) , \]
is such that $(Y_{n\wedge T})_{n\geq 0}$ is a $(\FF_n)_{n\geq 0}$-martingale. Apply the stopping theorem with the bounded stopping time $T'$:
\begin{align}\label{eq:sum-for-FK}
w(r) = \E\left[ W^{(r)}_0 \right] = \E\left[ W_{T'}^{(r)} \right] - \E\left[ \sum_{k=0}^{T'-1} \kW^{(r)}_k \mathrm{Remainder}(S_k, R_k, \delta_k) \right] .
\end{align}
By Proposition \ref{prop:convolution-w} 
\[ \frac{1}{90} |\mathrm{Remainder}(r, R, \delta)| \leq \P(\Lambda>R) + \P\left(\chi(\R)>\frac{\delta}{w(r-R)}\right) + (\sigma^2+1) w(r-R)^2(w(r-R)+\delta) , \]
thus on $\{ k < T'\}$ we have
\begin{align*}
\frac{1}{90} |\mathrm{Remainder}(S_k, R_k, \delta_k)| \leq \P(\Lambda>\RR) + \P\left(\chi(\R)>\frac{\underline{\delta}(y)}{w(y)}\right) + (\sigma^2+1) w(y)^2(w(y)+\underline{\delta}(y)) .
\end{align*}
We can then find a function $\underline{\delta}(y)\to 0$ as $y\to\infty$ decreasing and positive, together with a function $g(x) \to 0$ as $x\to 0$ increasing and positive, such that 
\begin{align*}
\P\left(\chi(\R)>\frac{\underline{\delta}(y)}{w(y)}\right) + (\sigma^2+1) w(y)^2(w(y)+ \underline{\delta}(y)) \leq \frac{1}{100} w(y)^2 g(w(y)) .
\end{align*}




Since by Lemma \ref{lem:discount-UI} the process $(\kW^{(r)}_{n\wedge T_a})_{n\geq 0}$ is a supermartingale we have 
\[ \E\left[ \kW^{(r)}_{n\wedge T'} \right] \leq 1 , \]
and given that $T'\leq A/w(x)$ we bound the sum in the right-hand side of \eqref{eq:sum-for-FK} by $A/w(x)$ times the upper bound for the remainder. This finishes the proof.

\label{prop:func-equation-phi}
Any limit $\phi$ in \eqref{eq:phi} satisfies
\begin{equation}
\phi(y) = \E^{y/\eta}\left[ \exp\left(-\frac{\sigma^2}{2} \int_0^{\tau_0^B} \phi\left(\eta B_u\right) \d u \right) \right] \quad \text{ for every } y\geq 0 .
\end{equation}

Fix $\nu>0$, $A>0$ and $y>0$, and let $r = x + \frac{y}{\sqrt{w(x)}}$ and $R_n = \RR = \frac{a}{\sqrt{w(x)}}$ for every $n$. Thanks to Lemma \ref{lem:continuity-w-broad} we can choose $a \in(0,a_0)$ such that that $w(x) \leq w(x-\RR) \leq (1+\nu) w(x)$ for every large enough $x$. 
Let and $\delta_n = \delta = \underline{\delta}(x-\RR)$ for every $n\geq 0$. Taking $x$ large enough ensures that $T_a > \tau_x$, hence $T' = \inf(\tau_x, A/w(x))$, and that $S_n-R_n \geq x-\RR$ on $\{T'>n\}$. 
We can then apply Corollary \ref{cor:Feynman-Kac}:
\[ \left| w(r) - \E\left[ W^{(r)}_{T'}\right] \right| \leq \frac{100 A}{w(x)}\left(\P(\Lambda>\RR) + w(x-\RR)^2 g(w(x-\RR))\right) \leq A w(x) g_1(x) \]
for some $g_1(x) \to 0$ as $x\to \infty$. 
We now aim to control 
\[ \E\left[ W^{(r)}_{T'}\right] = \E\left[ w(S_{T'}) \kW^{(r)}_{T'} \right] . \] 


Recall the expression from $\kW^{(r)}_n$ in \eqref{eq:def-Z}: 
\begin{multline*}
\kW^{(r)}_n = \left(\prod_{k=0}^{n-1} I_{k+1} \right) \exp\Bigg( - \underbrace{\sum_{k=0}^{n-1} \left( I_{k+1} w(S_{k+1}) - \E\left[I^{(S_k, \RR, \delta)} w(S_k - Z) \, | \, \FF_k\right] \right)}_{M_n} \\
-\frac{1}{2} \underbrace{ \sum_{k=0}^{n-1} I_{k+1} \int w(S_{k}-y) \d M_{S_k - S_{k+1}}^{(S_k, \RR, \delta)}(y)}_{Y_n} \Bigg) . 
\end{multline*}
The process $(M_{n\wedge T'})_{n\geq 0}$ is a martingale with increments bounded in absolute value by $w(x-\RR)$, and we have almost surely $w(x-\RR) T' \leq w(x-\RR) \frac{A}{w(x)} \leq A(1+\nu)$. By Doob's maximal inequality, since $\E[M_{T'}^2] \leq (A/w(x)) (1+\nu)^2 w(x)^2 \to 0$ as $x\to 0$, there exists $c_x\to 0$ as $x\to\infty$ such that 
\begin{equation}\label{eq:controle-Z-1}
\P\left( \sup_{0\leq k \leq A/w(x)} |M_{k\wedge T'}| \geq c_x \right) \leq c_x .
\end{equation}
On the other hand, writing 
\[ X_k := I_{k+1} \int w(S_{k}-z) \d M_{S_{k}-S_{k+1}}^{(S_k, \RR, \delta)}(z) \quad , \quad \tilde Y_n = \sum_{k=0}^{n-1} \E\left[ X_k \ | \ \FF_k \right] \]
then $\tilde Y_n$ is a predictable process such that $\tilde M_n := (Y_{n\wedge T'} - \tilde Y_{n\wedge T'})_{n\geq 0}$ is a martingale. By \eqref{eq:Palm-controle-M}, $0\leq X_k \leq \delta$ on $\{T'>k\}$, meaning that $(\tilde M_n)_{n\geq 0}$ is a martingale with increments bounded in absolute value by $\delta$. Hence $\E[\tilde M_n^2] \leq \delta \E[Y_{n\wedge T'}]$. By Doob's maximal inequality, since $\delta\to 0$ as $x\to\infty$ it thus suffices to show that $\E[Y_{n\wedge T'}]$ remains bounded as $x\to\infty$ to conclude that there exists $c'_x\to 0$ as $x\to\infty$ such that 
\begin{equation}\label{eq:controle-Z-2}
\P\left( \sup_{0\leq k \leq A/w(x)} |\tilde M_{k\wedge T'}| \geq c'_x \right) \leq c'_x .
\end{equation}

Let us compute $\E[X_k \, | \, \FF_{k}]$: for every $u$ large enough, 
\begin{align*}
\E\left[ I^{(u,\RR,\delta)} \int w(u-z) \d M_{Z}^{(u, \RR, \delta)}(z) \right] &= \E\left[ \ind{E(u,\RR,\delta)} \int \left(\int w(u-\ell) \d(\chi-\delta_z)(\ell)\right) \d\chi(z) \right] \\
&= \E\left[ \ind{E(u,\RR,\delta)} (\chi(\R)-1)\int w(u-z)\d\chi(z) \right] .
\end{align*}
Using again Lemma \ref{lem:continuity-w-broad}, for every large enough $x$ we have $w(u) \leq w(u-\RR) \leq (1+\nu)w(u)$ for every $u\geq x$. As $u\to\infty$ we have in addition that $\inf_{u\geq x} \P(E(u,\RR,\delta)) = \P(E(x,\RR,\delta)) \to 1$ as $x\to\infty$ --- recall that $\underline{\delta}$ was chosen in the proof of Corollary \ref{cor:Feynman-Kac} in such a way that $\underline{\delta}(y)/w(y) \to \infty$ as $y\to\infty$. Then since $w(u-j)/w(u) \to 1$ for every fixed $j$ as $u\to\infty$ by Lemma \ref{lem:continuity-w-broad}, and by \eqref{eq:Palm-controle-M} and the dominated convergence theorem, we have as $u\to\infty$ 
\begin{align*}
\frac{1}{w(u)} \E\left[ I^{(u,\RR,\delta)} \int w(u-z) \d M_{Z}^{(u, \RR, \delta)}(z) \right] \to \E\left[ \chi(\R)(\chi(\R)-1)\right] = \sigma^2 .
\end{align*}
Writing $d_v = \sup_{u\geq v} \left|\frac{1}{\sigma^2 w(u)} \E\left[ I^{(u,\RR,\delta)} \int w(u-z) \d M_{Z}^{(u, \RR, \delta)}(z) \right] - 1\right|$, we have $d_v \to 0$ as $v\to \infty$. 
The first consequence is that $\E[Y_{T'}] \leq (1+d_x) (A/w(x)) \sigma^2 w(x)$ 
which remains bounded as $x\to\infty$, thus finishing the proof of \eqref{eq:controle-Z-2}. 
In addition, as $x\to\infty$, for every $n$
\begin{equation}\label{eq:controle-Z-3}
\left| \frac{\tilde Y_{n\wedge T'}}{\sigma^2 \sum_{k=0}^{n\wedge T'-1} w(S_k)} - 1 \right| \leq d_x \to 0 .
\end{equation}

Write $\AA$ for the intersection of the complement of the events in \eqref{eq:controle-Z-1} and \eqref{eq:controle-Z-2}; on $\AA$, for $x$ large enough we have for every $n$ 
\[ \left| \kW^{(r)}_{n\wedge T'} - \exp\left(-\frac{\sigma^2}{2} \sum_{k=0}^{n\wedge T'-1} w(S_k) \right) \right| \leq 2(c_x + c'_x + d_x) . \]


