\label{lem:phit-taylor-expansion}
For every $p \in (1,\infty)$ and every random variable $W\in L^p$,
\[ \E\left[W \left(1 - \e^{-tD}\right)\right] = o\left(t^{\frac{p-1}{p}}\right) . \] 
For every $t\geq 0$ define
\[ f(t) := \E\left[\chi(\R) \e^{-tD}\right] -1 . \] 
Then $f(t) = o(t^{1/2})$, 
\begin{equation}\label{eq:phit-taylor-expansion}
\Phi_t(x) = x + \E\left[ \e^{-tD}-1 \right] + (x-1)f(t) + \frac{(x-1)^2}{2} \E\left[ (\chi(\R)^2 - \chi(\R))\e^{-t D} \right] + o((x-1)^2)
\end{equation} 
with a $o((x-1)^2)$ that is uniform over all $t\geq 0$, and as $t\to 0$ with $t\geq 0$
\begin{equation}\label{eq:htinfty-taylor-expansion}
1-h_t(\infty) \sim \sqrt{\frac{2 t}{\sigma^2}} \ .
\end{equation}

Using Hölder's inequality, letting $q = \frac{p}{p-1}$
\[ \left| \E\left[W \left(1 - \e^{-tD}\right)\right]\right| \leq \E\left[|W|^p\right]^{1/p} \E\left[\left(1 - \e^{-tD}\right)^q\right]^{1/q} . \]
Split the second expectation on $\{ tD>\varepsilon\}$ and $\{tD\leq \varepsilon\}$, and use $|\e^{-x}-1|\leq x$ for $x\geq 0$:
\begin{align*}
\E\left[\left(1 - \e^{-tD}\right)^q\right] &\leq  \E\left[\left(1 - \e^{-tD}\right)^q \ind{tD \leq \varepsilon}\right] +  \E\left[\left(1 - \e^{-tD}\right)^q \ind{tD>\varepsilon} \right] \\
&\leq \varepsilon^{q-1} \E[tD] + \P\left( D > \frac{\varepsilon}{t}\right) \\
&\leq \varepsilon^{q-1} t + \frac{2t}{\varepsilon \psi_D(\varepsilon/t)} 
\end{align*}
with $\psi_D$ given by Lemma \ref{lem:refined-Markov}: we can take $\varepsilon = \varepsilon(t)$ that goes to zero sufficiently slowly that the above expression is $o(t)$, proving our claim. The bound on $f$ follows from it with $p=2$ and $W = \chi(\R)$. Next is the Taylor expansion of $\Phi_t(x)$ near $x=1$ (with $x\leq 1$): for every $\varepsilon>0$
\begin{multline*}
\left| \Phi_t(x) - \E\left[ \e^{-tD}\left( 1 + \chi(\R) \ln x + \frac{\chi(\R)^2}{2} (\ln x)^2 \right) \right] \right| \\
\leq \E\left[ \left| \e^{\chi(\R)\ln x} - 1 - \chi(\R) \ln x - \frac{\chi(\R)^2}{2} (\ln x)^2 \right| \right] .
\end{multline*}
Split it on $\{ \chi(\R)\ln x < -\varepsilon\}$ and $\{\chi(\R)\ln x \geq -\varepsilon\}$, using $|\e^{-u} - 1 - u - u^2/2| \leq \omega(u) u^2$ for $u\leq 0$ with $\omega$ increasing and $\omega(u) \to 0$ as $u\to 0$:
\begin{equation}\label{eq:lem-phit-taylor-exp-1}
\E\left[ \left| \e^{\chi(\R)\ln x} - 1 - \chi(\R) \ln x - \frac{\chi(\R)^2}{2} (\ln x)^2 \right| \ind{\chi(\R)\ln x > -\varepsilon} \right] \leq \omega(\varepsilon) (\ln x)^2 \E\left[ \chi(\R)^2 \right] .
\end{equation}
On the other hand, using first $|\e^{-x}-1| \leq 1$, then Lemma \ref{lem:refined-Markov} to obtain $\psi_\chi$ (increasing to $+\infty$) and $C := \E[\chi(\R)^2 \psi_\chi(\chi(\R))]$,
\begin{align}
& \E\left[ \left| \e^{\chi(\R)\ln x} - 1 - \chi(\R) \ln x - \frac{\chi(\R)^2}{2} (\ln x)^2 \right| \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\leq \P\left( \chi(\R) \leq \frac{-\varepsilon}{\ln x} \right) - (\ln x) \E\left[ \chi(\R)\ind{\chi(\R)\ln x \leq -\varepsilon} \right] + \frac{(\ln x)^2}{2} \E\left[ \chi(\R)^2 \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\leq \frac{C}{\varepsilon^2 \psi_\chi(-\varepsilon/\ln x)} (\ln x)^2 + \frac{(\ln x)^2}{\varepsilon \psi_\chi(-\varepsilon/\ln x)} \E\left[ \chi(\R)^2 \psi_\chi(\chi(\R)) \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\quad + \frac{(\ln x)^2}{2 \psi_\chi(-\varepsilon/\ln x)} \E\left[ \chi(\R)^2 \psi_\chi(\chi(\R)) \ind{\chi(\R)\ln x \leq -\varepsilon} \right] \nonumber \\
&\leq C\left( \varepsilon^{-2} + \varepsilon^{-1} + \frac 1 2 \right) \frac{(\ln x)^2}{\psi_\chi(-\varepsilon / \ln x)} .  \label{eq:lem-phit-taylor-exp-2}
\end{align}
We can find $\varepsilon = \varepsilon(x)$ that goes to $0$ sufficiently slowly as $x\to 1$ such that the right-hand side of \eqref{eq:lem-phit-taylor-exp-1} and \eqref{eq:lem-phit-taylor-exp-2} are both $o((x-1)^2)$, uniformly in $t\geq 0$. To prove \eqref{eq:phit-taylor-expansion} we need to control
\begin{align*}
&\Bigg| \E\left[ \e^{-tD}\left( 1 + \chi(\R) \ln x + \frac{\chi(\R)^2}{2} (\ln x)^2 \right) \right] \\
&\qquad - x - \E\left[ \e^{-tD}-1 \right] - (x-1) \left(\E\left[\chi(\R) \e^{-tD}\right]-1\right) - \frac{(x-1)^2}{2}\E\left[ \e^{-tD}\left( \chi(\R)^2 - \chi(\R)\right)\right] \Bigg| \\
&\leq \E\left[ \chi(\R) \left|\ln x - (x-1) + \frac{(x-1)^2}{2}\right| + \chi(\R)^2 \left|\ln(x)^2 - (x-1)^2\right| \right] = o((x-1)^2)
\end{align*}
uniformly in $t\geq 0$. 

Let us now prove \eqref{eq:htinfty-taylor-expansion} from the previous estimates. 
Since $\Phi_t'(x) = \E[\chi(\R) \e^{-t D} x^{\chi(\R)}]$ we have $0\leq \Phi_t'\leq 1$ on $[0,1]$; in addition $\Phi_t(1) \to 1$ as $t\to 0$, so that $h_t(\infty) \to 1$ as $t\to 0$. Hence using \eqref{eq:phit-taylor-expansion}, writing for simplicity $x := 1-h_t(\infty)$ in the rest of the proof
\begin{align*}
1-x = 1-x + \E\left[\e^{-tD}-1\right] - x f(t) + \frac{\sigma^2 + o(1)}{2} x^2 .
\end{align*}
Using that $\E[\e^{-tD}-1] \sim t$ as $t\to 0$ with $t\geq 0$, the solution must be
\begin{align*}
1-h_t(\infty) = \frac{-f(t) + \sqrt{f(t)^2 + 2 \sigma^2 t + o(t)}}{\sigma^2 + o(1)} \sim \sqrt{\frac{2 t}{\sigma^2}} \ .
\end{align*}
This finishes the proof of Lemma \ref{lem:phit-taylor-expansion}.

\begin{align}
& \E\left[ \left| \e^{\chi(\R)\ln x} - 1 - \chi(\R) \ln x - \frac{\chi(\R)^2}{2} (\ln x)^2 \right| \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\leq \P\left( \chi(\R) \leq \frac{-\varepsilon}{\ln x} \right) - (\ln x) \E\left[ \chi(\R)\ind{\chi(\R)\ln x \leq -\varepsilon} \right] + \frac{(\ln x)^2}{2} \E\left[ \chi(\R)^2 \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\leq \frac{C}{\varepsilon^2 \psi_\chi(-\varepsilon/\ln x)} (\ln x)^2 + \frac{(\ln x)^2}{\varepsilon \psi_\chi(-\varepsilon/\ln x)} \E\left[ \chi(\R)^2 \psi_\chi(\chi(\R)) \ind{\chi(\R)\ln x \leq -\varepsilon} \right]  \nonumber \\
&\quad + \frac{(\ln x)^2}{2 \psi_\chi(-\varepsilon/\ln x)} \E\left[ \chi(\R)^2 \psi_\chi(\chi(\R)) \ind{\chi(\R)\ln x \leq -\varepsilon} \right] \nonumber \\
&\leq C\left( \varepsilon^{-2} + \varepsilon^{-1} + \frac 1 2 \right) \frac{(\ln x)^2}{\psi_\chi(-\varepsilon / \ln x)} .  \label{eq:lem-phit-taylor-exp-2}
\end{align}

\label{lem:speed-cv-expectation-Et}
Let $W \in L^2$, then as $t\to 0$
\begin{equation}
\E[W] - \E\left[ \e^{-tD} h_t(\infty)^{\chi(\R)-1} W \right] = \sqrt{\frac{2t}{\sigma^2}} \ \E[ W(\chi(\R)-1) ] + o(t^{1/2}) .
\end{equation}

Write
\begin{align*}
&\E[W] - \E\left[ \e^{-tD} h_t(\infty)^{\chi(\R)-1} W \right] - (1-h_t(\infty)) \E[ W(\chi(\R)-1) ]  \\
&= \E\left[ W\left( 1 - \e^{-tD}h_t(\infty)^{\chi(\R)-1} - (1-h_t(\infty))(\chi(\R)-1) \right)\right] \\
&= \E\left[ W\left(1 + (h_t(\infty)-1)(\chi(\R)-1) - h_t(\infty)^{\chi(\R)-1} + h_t(\infty)^{\chi(\R)-1}\left( 1-\e^{-tD} \right) \right)\right] .
\end{align*}
Then the absolute value of the left-hand side is smaller than 
\begin{align*}
\E\left[|W| \left|1 + (h_t(\infty)-1)(\chi(\R)-1) - h_t(\infty)^{\chi(\R)-1}\right|\right] + h_t(\infty)^{-1} \E\left[|W| \left( 1-\e^{-tD} \right)\right] .
\end{align*}
We use Lemma \ref{lem:phit-taylor-expansion} and the fact that $h_t(\infty)\to 1$ to bound the second term by $o(t^{1/2})$ as $t\to 0$. The Cauchy--Schwarz inequality and the same kind of control as in the proof of Lemma \ref{lem:phit-taylor-expansion} can be used to bound the first term by $o(1-h_t(\infty)) = o(t^{1/2})$. We conclude by using the asymptotic of $1-h_t(\infty)$ from Lemma \ref{lem:phit-taylor-expansion}.

\begin{align*}
&\E[W] - \E\left[ \e^{-tD} h_t(\infty)^{\chi(\R)-1} W \right] - (1-h_t(\infty)) \E[ W(\chi(\R)-1) ]  \\
&= \E\left[ W\left( 1 - \e^{-tD}h_t(\infty)^{\chi(\R)-1} - (1-h_t(\infty))(\chi(\R)-1) \right)\right] \\
&= \E\left[ W\left(1 + (h_t(\infty)-1)(\chi(\R)-1) - h_t(\infty)^{\chi(\R)-1} + h_t(\infty)^{\chi(\R)-1}\left( 1-\e^{-tD} \right) \right)\right] .
\end{align*}

