\nonumber &\geq \frac{\ln(1+w_r(t))}{w_t(r)}\P(U_n^t \geq r_y) + \E\left[ \frac{\ln(1+w_t(r+r_y-U_n^t))}{w_t(r)} \ind{U_n^t<r_y , |U_n^t-U_n^0|\leq \delta\sqrt{n}} \right]\\
\nonumber &\geq \frac{\ln(1+w_r(t))}{w_t(r)}\P(U_n^0 \geq r_y-\delta\sqrt{n}) \\
\nonumber &\qquad - \underset{(a)}{\underbrace{\P\left(|U_n^t - U_n^0|>\delta\sqrt{n}\right)}} - \underset{(b)}{\underbrace{\P\left( U_n^0 \geq r_y-\delta\sqrt{n}, U_n^t < r_y, |U_n^t-U_n^0|\leq \delta\sqrt{n} \right)}} \\
\nonumber &\qquad + \E\left[ \frac{\ln(1+w_t(r+r_y-U_n^0 + \delta\sqrt{n}))}{w_t(r)} \ind{U_n^0 < r_y+\delta\sqrt{n}} \right] \\
&\qquad - \underset{(c)}{\underbrace{\P\left( |U_n^t - U_n^0| > \delta\sqrt{n} \right)}} - \underset{(d)}{\underbrace{\P\left( |U_n^t-U_n^0|\leq \delta\sqrt{n}, U_n^t\geq r_y, U_n^0<r_y+\delta\sqrt{n} \right)}} \label{eq:discounted-expectation-X}
\end{align}
where we used that $w_t$ is a decreasing function and $0< \ln(1+x)/x \leq 1$ for $x>0$. Terms $(b)$ and $(d)$ are clearly smaller than
\[ \P(U_n^0 \in [r_y - \delta\sqrt{n}, r_y+\delta\sqrt{n}) ) . \]
The central limit theorem gives us a sequence $\omega_1(n) \to 0$ as $n\to\infty$ and a constant $c$ such that this probability is smaller than $c\delta + \omega_1(n)$. On the other hand, by Bienaymé--Chebyshev's inequality
\[ \P(|U_n^t-U_n^0|>\delta\sqrt{n}) \leq \frac{\E[(U_1^t - U_1^0)^2]}{\delta^2} , \]
which goes to zero as $t\to 0$ by \eqref{eq:coupling-first-step}. 

Let $(B_u)_{u\geq 0}$ be a centered standard Brownian motion. Fix some $s>0$, and from now on set $n = n(r) = \lfloor \eta^{-2} s w_t(r)^{-1}\rfloor$. The sequence $U_n^0 (\eta^2 n)^{-1/2}$ converges to $B_1$ in distribution as $r\to\infty$, so that $U_n^0/r_y$ converges to $y^{-1} B_s$. 
Assume that \eqref{eq:2continuity-ratio-vol-right} holds with the right-hand side being replaced by some bounded, non-increasing function $f(y)$. Then 
\begin{multline*}
\liminf_{r\to\infty} \E\left[ \frac{\ln\left(1+w_t\left(r+r_y+\delta\sqrt{n} - U_n^0\right)\right)}{w_t(r)} \ind{U_n^0 < r_y\left(1 + \frac{\delta \sqrt{s}}{\eta}\right)} \right] \\
\geq \E\left[ f\left( y\left[ 1 + \frac{\delta\sqrt{s}}{\eta} \right] - B_s \right) \ind{y\left[ 1 + \frac{\delta\sqrt{s}}{\eta} \right] - B_s > 0} \right] .
\end{multline*}
We can check this by taking a coupling of the sequence $U_n^0 (\eta^2 n)^{-1/2}$ that converges a.s. towards $B_1$ by the Skorokhod representation theorem, then using the monotonicity of $f$ with Fatou's Lemma. Clearly $f(y) = \ind{y\leq 0}$ works. 

Since $w_t(r)\to 0$ as $r\to\infty$, taking the liminf of \eqref{eq:discounted-expectation-X} as $r\to\infty$, 
\begin{multline*}
\liminf_{r\to\infty} \E^{(t)}[\chi(\R)]^{-n} \frac{-\E^{(t)}[X]}{w_t(r)} \\
\geq \P\left(B_s \geq y-\frac{\delta\sqrt{s}}{\eta} \right) + \E\left[ f\left( y\left[ 1 + \frac{\delta\sqrt{s}}{\eta} \right] - B_s \right) \ind{y\left[ 1 + \frac{\delta\sqrt{s}}{\eta} \right] > B_s} \right] - 2c\delta .
\end{multline*}
Take $\delta\to 0$:
\begin{equation}\label{eq:liminf-EX}
\liminf_{r\to\infty} \E^{(t)}[\chi(\R)]^{-n} \frac{-\E^{(t)}[X]}{w_t(r)}
\geq \P(B_s\geq y) + \E\left[\ind{B_s < y} f\left(y-B_s\right)\right] .
\end{equation}
On the other hand, by \eqref{eq:second-moment-Gr2} 
and taking $t_0>0$ small enough that $\E^{(t)}[\chi(\R)]^{-1} \mathrm{Var}^{(t)}(\chi(\R))\leq 2\sigma^2$ for every $t\leq t_0$, 
we get uniformly in $t\in[0,t_0]$, 
\begin{align*}
\E^{(t)}[X^2] \leq (\ln \tilde h_t(r))^2 \E^{(t)}[G_n(\R)^2] \leq (\ln \tilde h_t(r))^2 \E^{(t)}[\chi(\R)]^n (1+2n\sigma^2) ,

\end{align*}
Since $n \ln \tilde h_t(r) \ulim r \infty s \eta^{-2}$ as $r\to\infty$ from the definition of $n$, 
\begin{equation}\label{eq:liminf-EX2}
\limsup_{r\to\infty} \E^{(t)}[\chi(\R)]^{-n} \frac{\E^{(t)}[X^2]}{w_t(r)} \leq \frac{2 s \sigma^2}{\eta^2} .
\end{equation}
Combining \eqref{eq:liminf-EX} and \eqref{eq:liminf-EX2}, 
\begin{equation}\label{eq:2why-t-must-vary}
\liminf_{r\to\infty} \frac{w_t(r+r_y)}{w_t(r)} \E^{(t)}[\chi(\R)]^{-n} 
\geq \E\left[ \ind{B_s\geq y} + \ind{B_s<y} f\left(y-B_s\right)\right] - s \frac{\sigma^2}{\eta^2} . 
\end{equation}
Recall from \eqref{eq:asymptotic-expectation-chi-vol} that $1-\E^{(t)}[\chi(\R)] \sim \sqrt{2t\sigma^2}$ as $t\to 0$. Since $\liminf_{r\to\infty} r^2 w_t(r) \geq c(\alpha) \frac{6\eta^2}{\sigma^2} > 0$ by Lemma \ref{lem:positivity-c-alpha} and since $t = t(r,\alpha)$ we get 
\begin{align*}
\liminf_{r\to\infty} \frac{w_t(r+r_y)}{w_t(r)} &\geq \exp\left(- \frac{s}{w_t(r) \eta^2}\frac{\alpha}{r^2} \right) \left\{ \E\left[ \ind{B_s\geq 1} + \ind{B_s<1} f\left(y-yB_s\right)\right] - s \frac{\sigma^2}{\eta^2} \right \} \\
&\geq \E\left[ \ind{B_s\geq 1} + \ind{B_s<1} f\left(y-yB_s\right)\right] - \frac{s}{\eta^2}\left(\sigma^2 + \frac{\alpha}{c(\alpha)}\right) .

\end{align*}

The rest of the proof follows that of Lemma \ref{lem:continuity-w-broad}:
