\[ A = - I^{(x,\RR,\delta)}w_t(x-Z) + \E^{(t)}\left[I^{(x,\RR,\delta)} w_t(x-Z)\right] \quad , \quad B = - \frac{I^{(x,\RR,\delta)}} 2 \int w_t(x-y) \d M_Z^{(x,\RR,\delta)}(y) \]
